<script setup lang="ts">
import { onMounted, ref } from 'vue';import http from '@/api/http';import { ElMessage } from 'element-plus'
type Msg={role:'user'|'assistant'|'system';content:string}
const available=ref(false),input=ref(''),loading=ref(false),messages=ref<Msg[]>([{role:'assistant',content:'你好，我是 ProcureMind AI 采购助手。你可以让我查询物资、供应商、订单与库存，Agent 未启动时不影响其他业务功能。'}])
onMounted(async()=>{try{const s:any=await http.get('/ai/status');available.value=s.enabled}catch{}})
async function send(){if(!input.value.trim()||loading.value)return;const text=input.value;input.value='';messages.value.push({role:'user',content:text});const reply:Msg={role:'assistant',content:''};messages.value.push(reply);loading.value=true;try{const response=await fetch('/api/v1/ai/chat/stream',{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${localStorage.getItem('pm_access_token')}`},body:JSON.stringify({message:text})});if(!response.ok)throw new Error((await response.json()).message||'AI助手不可用');const reader=response.body?.getReader(),decoder=new TextDecoder();while(reader){const {done,value}=await reader.read();if(done)break;const chunk=decoder.decode(value,{stream:true});for(const line of chunk.split('\n')){const raw=line.startsWith('data:')?line.slice(5).trim():line.trim();if(!raw||raw==='[DONE]')continue;try{const e=JSON.parse(raw);reply.content+=e.content||e.delta||e.message||''}catch{reply.content+=raw}}}}catch(e:any){reply.content='AI助手暂时不可用。普通采购业务可继续使用。';ElMessage.warning(e.message)}finally{loading.value=false}}
</script>
<template><div class="page assistant"><div class="page-head"><div><h1>AI采购助手</h1><p>Agent可插拔，所有调用由Spring统一鉴权与审计</p></div><el-tag :type="available?'success':'info'">{{available?'Agent 已连接':'Agent 未启用'}}</el-tag></div><div class="chat panel"><div class="messages"><div v-for="(m,i) in messages" :key="i" :class="['message',m.role]"><div class="who">{{m.role==='user'?'我':'ProcureMind AI'}}</div><div class="bubble">{{m.content}}<span v-if="loading&&i===messages.length-1" class="cursor">▍</span></div></div></div><div class="composer"><el-input v-model="input" type="textarea" :rows="3" :disabled="!available" :placeholder="available?'例如：查询低库存物资并给出采购建议':'请先在后端启用 Agent 集成'" @keydown.ctrl.enter="send"/><div><small>Ctrl + Enter 发送</small><el-button type="primary" :loading="loading" :disabled="!available" @click="send">发送</el-button></div></div></div></div></template>
<style scoped>.assistant{height:calc(100vh - 64px);display:flex;flex-direction:column}.chat{flex:1;min-height:0;display:flex;flex-direction:column;overflow:hidden}.messages{flex:1;overflow:auto;padding:28px}.message{max-width:78%;margin-bottom:24px}.message.user{margin-left:auto}.who{font-size:12px;color:#8994a6;margin-bottom:7px}.user .who{text-align:right}.bubble{white-space:pre-wrap;line-height:1.7;padding:14px 17px;border-radius:13px;background:#f0f4fa}.user .bubble{background:#0b5cff;color:white}.composer{border-top:1px solid #e8edf5;padding:16px 20px}.composer>div{display:flex;justify-content:space-between;align-items:center;margin-top:8px}.composer small{color:#929bab}.cursor{animation:blink 1s infinite}@keyframes blink{50%{opacity:0}}</style>
